import base64
import json
import os
from typing import Any, Dict, Optional

import requests


OPENAI_TABLE_MODEL = os.getenv("OPENAI_TABLE_MODEL", "gpt-4o-mini")
OPENAI_API_KEY_ENV = "OPENAI_API_KEY"
OPENAI_CHAT_COMPLETIONS_URL = "https://api.openai.com/v1/chat/completions"


def _document_to_data_url(document_bytes: bytes, mime_type: str = "application/pdf") -> str:
    encoded = base64.b64encode(document_bytes).decode("ascii")
    return f"data:{mime_type};base64,{encoded}"


def extract_tables_from_document(document_bytes: bytes, mime_type: str = "application/pdf", extra_instructions: Optional[str] = None) -> Dict[str, Any]:
    api_key = os.getenv(OPENAI_API_KEY_ENV)
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is required")

    prompt = "Extract table structure from this document. Return a JSON object with tables, rows, and cells preserving cell text, row order, and column spans if present."
    if extra_instructions:
        prompt = f"{prompt} {extra_instructions}"

    payload: Dict[str, Any] = {
        "model": OPENAI_TABLE_MODEL,
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {"type": "image_url", "image_url": {"url": _document_to_data_url(document_bytes, mime_type)}},
                ],
            }
        ],
        "temperature": 0,
    }

    response = requests.post(
        OPENAI_CHAT_COMPLETIONS_URL,
        headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
        data=json.dumps(payload),
        timeout=120,
    )
    response.raise_for_status()
    data = response.json()
    content = data["choices"][0]["message"]["content"].strip()
    try:
        return json.loads(content)
    except json.JSONDecodeError:
        return {"tables": [], "raw": content}


def extract_tables_from_file(path: str, mime_type: Optional[str] = None, extra_instructions: Optional[str] = None) -> Dict[str, Any]:
    with open(path, "rb") as f:
        document_bytes = f.read()
    if mime_type is None:
        lower = path.lower()
        if lower.endswith(".png"):
            mime_type = "image/png"
        elif lower.endswith(".jpg") or lower.endswith(".jpeg"):
            mime_type = "image/jpeg"
        elif lower.endswith(".webp"):
            mime_type = "image/webp"
        else:
            mime_type = "application/pdf"
    return extract_tables_from_document(document_bytes, mime_type=mime_type, extra_instructions=extra_instructions)

import os
from typing import Any, Dict, List, Optional

import requests


OPENAI_API_URL = "https://api.openai.com/v1/responses"
OPENAI_MODEL = os.getenv("OPENAI_MODEL", "gpt-5.4-mini")


def extract_key_values(document_text: str, schema_hint: Optional[str] = None) -> Dict[str, Any]:
    api_key = os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is required")

    prompt_parts: List[str] = [
        "Extract key-value pairs from the following form-like document text.",
        "Return JSON with a top-level object containing a 'key_values' array.",
        "Each array item must have 'key', 'value', and optionally 'confidence'.",
        "Preserve field names as written when possible.",
    ]
    if schema_hint:
        prompt_parts.append(f"Schema hint: {schema_hint}")
    prompt_parts.append(f"Document text:\n{document_text}")

    payload = {
        "model": OPENAI_MODEL,
        "input": [{"role": "user", "content": [{"type": "input_text", "text": "\n".join(prompt_parts)}]}],
        "response_format": {"type": "json_object"},
    }

    response = requests.post(
        OPENAI_API_URL,
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json=payload,
        timeout=60,
    )
    response.raise_for_status()
    data = response.json()

    output_text = ""
    for item in data.get("output", []):
        for content in item.get("content", []):
            if content.get("type") in {"output_text", "text"}:
                output_text += content.get("text", "")

    if not output_text and isinstance(data.get("output_text"), str):
        output_text = data["output_text"]

    if not output_text:
        return {"key_values": []}

    parsed = requests.utils.json.loads(output_text)
    if isinstance(parsed, dict) and "key_values" in parsed:
        return parsed
    return {"key_values": parsed if isinstance(parsed, list) else []}

